// Cross-validation: the browser checker must agree with SymPy on every vector
// generated by content/catchai/exercises.py, and must refuse (not guess) on
// inputs outside its provable class.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { checkExpression, checkExtremum, checkPoints, parsePoly, polyLatex } from "./mathcheck";
import type { Pack } from "./types";

const root = resolve(__dirname, "../../..");
const pack: Pack = JSON.parse(readFileSync(resolve(root, "frontend/public/packs/calculus1.json"), "utf8"));
const vectors: { exercise: string; input: string; expect: string }[] = JSON.parse(
  readFileSync(resolve(root, "content/packs/checker_vectors.json"), "utf8"),
);
const ex = (id: string) => pack.exercises.find((e) => e.id === id)!;

describe("agrees with SymPy on generated vectors", () => {
  for (const v of vectors) {
    it(`${v.exercise}: ${v.input} -> ${v.expect}`, () => {
      const e = ex(v.exercise);
      const a = e.answer;
      const verdict =
        a.kind === "expression" ? checkExpression(v.input, a.coeffs)
        : a.kind === "points" ? checkPoints(v.input, a.values)
        : checkExtremum(v.input.split("|")[0], v.input.split("|")[1], a);
      expect(verdict.status).toBe(v.expect);
    });
  }
});

describe("parser details", () => {
  it("never treats an approximation as exact", () => {
    expect(checkPoints("0.333", ["1/3"]).status).toBe("incorrect");
    expect(checkPoints("1/3", ["1/3"]).status).toBe("correct");
  });
  it("reports unreadable input as syntax, not as wrong", () => {
    expect(checkExpression("12x^3 - (6", { "3": "12" }).status).toBe("syntax");
    expect(checkExpression("", { "0": "1" }).status).toBe("syntax");
    expect(checkPoints("x^2", ["1"]).status).toBe("syntax");
  });
  it("handles unicode minus, superscripts and implicit products", () => {
    expect(checkExpression("3x² − 6x", { "2": "3", "1": "-6" }).status).toBe("correct");
    expect(checkExpression("x(x+1)(x-1)", { "3": "1", "1": "-1" }).status).toBe("correct");
  });
  it("previews what it understood", () => {
    expect(polyLatex(parsePoly("12x^3 - 6/x^4 - 5"))).toBe("12x^{3} - 5 - 6x^{-4}");
  });
  it("every exercise's own answer is accepted", () => {
    for (const e of pack.exercises) {
      const a = e.answer;
      if (a.kind === "expression") {
        const s = Object.entries(a.coeffs).map(([k, c]) => `(${c})x^(${k})`).join(" + ");
        expect(checkExpression(s, a.coeffs).status).toBe("correct");
      } else if (a.kind === "points") {
        expect(checkPoints(a.values.join(", "), a.values).status).toBe("correct");
      } else {
        expect(checkExtremum(a.value, a.at.join(","), a).status).toBe("correct");
      }
    }
  });
});
